    public static func append(
        _ a: Vector,
        addingCount: Int,
        toUnchecked output: inout OutputSpan<Lane>
    ) {
        assert(addingCount >= 0 && addingCount <= laneCount, "Count out of bounds")
        assert(
            addingCount <= output.freeCapacity,
            "OutputSpan has less free capacity than the count"
        )
        unsafe output.withUnsafeMutableBufferPointer { buffer, initializedCount in
            unsafe cvectorization_ops_store_first_f64(
                a,
                buffer.baseAddress?.advanced(by: initializedCount),
                addingCount
            )
            initializedCount &+= addingCount
        }
    }

    @export(implementation) @inline(always)
    public static func store(_ a: Vector, to: UnsafeMutablePointer<Lane>, where mask: Mask) {
        unsafe cvectorization_ops_store_where_f64(a, mask.raw, to)
    }

    @available(SwiftStdlib 5.1, *)
    @export(implementation) @inline(always)
    public static func store(_ a: Vector, to span: inout MutableSpan<Lane>, where mask: Mask) {
        precondition(span.count >= laneCount, "Span has fewer elements than a vector has lanes")
        unsafe store(a, toUnchecked: &span, where: mask)
    }

    @available(SwiftStdlib 5.1, *)
    @unsafe @export(implementation) @inline(always)
    public static func store(
        _ a: Vector,
        toUnchecked span: inout MutableSpan<Lane>,
        where mask: Mask
    ) {
        assert(span.count >= laneCount, "Span has fewer elements than a vector has lanes")
        span.withUnsafeMutableBufferPointer {
            unsafe cvectorization_ops_store_where_f64(a, mask.raw, $0.baseAddress.unsafelyUnwrapped)
        }
    }

    @export(implementation) @inline(always)
    public static func storeRepeating(_ value: Lane, count: Int, to: UnsafeMutablePointer<Lane>) {
        unsafe cvectorization_ops_store_repeating_f64(count, value, to)
    }

    @available(SwiftStdlib 5.1, *)
    @export(implementation) @inline(always)
    public static func storeRepeating(_ value: Lane, to span: inout MutableSpan<Lane>) {
        span.withUnsafeMutableBufferPointer {
            unsafe cvectorization_ops_store_repeating_f64(
                Swift.min($0.count, laneCount),
                value,
                $0.baseAddress
            )
        }
    }

    @export(implementation) @inline(always)
    public static func copy(count: Int, from: UnsafePointer<Lane>, to: UnsafeMutablePointer<Lane>) {
        unsafe cvectorization_ops_copy_f64(count, from, to)
    }

    @available(SwiftStdlib 5.1, *)
    @export(implementation) @inline(always)
    public static func copy(from: Span<Lane>, to: inout MutableSpan<Lane>) {
        from.withUnsafeBufferPointer { fromBuffer in
            to.withUnsafeMutableBufferPointer { toBuffer in
                unsafe cvectorization_ops_copy_f64(
                    Swift.min(fromBuffer.count, toBuffer.count, laneCount),
                    fromBuffer.baseAddress,
                    toBuffer.baseAddress
                )
            }
        }
    }

    @export(implementation) @inline(always)
    public static func store(_ a: HalfVector, to: UnsafeMutablePointer<Lane>) {
        unsafe cvectorization_ops_store_half_f64(a.raw, to)
    }

    @available(SwiftStdlib 5.1, *)
    @export(implementation) @inline(always)
    public static func store(_ a: HalfVector, to span: inout MutableSpan<Lane>) {
        precondition(
            span.count >= laneCount / 2,
            "Span has fewer elements than half a vector has lanes"
        )
        unsafe store(a, toUnchecked: &span)
    }

    @available(SwiftStdlib 5.1, *)
    @unsafe @export(implementation) @inline(always)
    public static func store(_ a: HalfVector, toUnchecked span: inout MutableSpan<Lane>) {
        assert(span.count >= laneCount / 2, "Span has fewer elements than half a vector has lanes")
        span.withUnsafeMutableBufferPointer {
            unsafe cvectorization_ops_store_half_f64(a.raw, $0.baseAddress.unsafelyUnwrapped)
        }
    }

    @available(SwiftStdlib 5.1, *)
    @export(implementation) @inline(always)
    public static func append(_ a: HalfVector, to output: inout OutputSpan<Lane>) {
        precondition(
            output.freeCapacity >= laneCount / 2,
            "OutputSpan has less free capacity than half a vector has lanes"
        )
        unsafe append(a, toUnchecked: &output)
    }

    @available(SwiftStdlib 5.1, *)
    @unsafe @export(implementation) @inline(always)
    public static func append(_ a: HalfVector, toUnchecked output: inout OutputSpan<Lane>) {
        assert(
            output.freeCapacity >= laneCount / 2,
            "OutputSpan has less free capacity than half a vector has lanes"
        )
        unsafe output.withUnsafeMutableBufferPointer { buffer, initializedCount in
            unsafe cvectorization_ops_store_half_f64(
                a.raw,
                buffer.baseAddress.unsafelyUnwrapped + initializedCount
            )
            initializedCount &+= laneCount / 2
        }
    }

}
